export const title = "How to Choose a Folding Desk for Everyday Work";
export const metaTitle = "How to Choose a Folding Desk for Everyday Work";
export const metaDescription = "Compare the working surface, leg clearance, deployed supports, locking mechanism, folded dimensions, and handling weight. Read the instructions for.";
export const author = "Jamie Cole, Lead Product Researcher";
